INSERT INTO `communication_templates` VALUES (1,'email','byoc_order_confirmed_customer','Your Custom Cake Order Is Confirmed - {{order_number}}','<div style=\"background:#f0fdf4;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#166534;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"{{business_logo}}\" alt=\"{{business_name}} Logo\" style=\"height:72px;display:block;width:auto;max-width:260px;background:rgba(255,255,255,0.96);padding:10px 16px;border-radius:16px;box-sizing:border-box;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">BYOC Order Confirmed (Customer)</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">Your custom cake order has been confirmed by Cakeouflage.</p><div style=\"margin-top:28px;background:#dcfce7;border:1px solid #bbf7d0;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Order Number:</strong> {{order_number}}</p><p><strong>Order Total:</strong> {{currency}} {{grand_total}}</p><p><strong>Advance Paid:</strong> {{currency}} {{advance_amount}}</p><p><strong>Remaining Balance:</strong> {{currency}} {{remaining_balance}}</p><p><strong>Delivery Address:</strong> {{delivery_address}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">Our team will contact you to confirm delivery details.</div></div><div style=\"background:#14532d;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team {{business_name}}</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; {{business_website}}</p><p style=\"color:#d7c6cc;font-size: